<template>
  <div class="page-container rank-page"><div class="page-head"><div><h2>{{ userStore.regionName }}粮食生产进度排行榜</h2><p>{{ levelHint }}，支持按落实、播种和收获进度切换。</p><div class="crumbs"><el-button link :disabled="!selectedRegion" @click="resetDrill">全省</el-button><span v-if="selectedRegion">/ {{ selectedRegion.name }}</span></div></div><div class="head-tools"><el-select v-model="selectedRegionCode" clearable placeholder="选择区域下钻" style="width:160px" @change="drillDown"><el-option v-for="item in rankData" :key="item.code" :label="item.name" :value="item.code"/></el-select><el-radio-group v-model="metric"><el-radio-button value="implementRate">落实率</el-radio-button><el-radio-button value="sowRate">播种率</el-radio-button><el-radio-button value="harvestRate">收获率</el-radio-button></el-radio-group></div></div>
    <div class="stat-grid"><StatCard label="参评地区" :value="rankData.length" unit="个" icon="OfficeBuilding" /><StatCard label="平均落实率" :value="average('implementRate')" unit="%" icon="TrendCharts" color="#2e9e5b" /><StatCard label="平均播种率" :value="average('sowRate')" unit="%" icon="DataLine" color="#e6a23c" /><StatCard label="平均收获率" :value="average('harvestRate')" unit="%" icon="CircleCheck" color="#9b59b6" /></div>
    <div class="top-grid"><div v-for="(item,index) in sortedData.slice(0,3)" :key="item.code" class="top-card" :class="'top-' + (index + 1)"><span class="medal">第{{ index+1 }}名</span><h3>{{ item.name }}</h3><strong>{{ item[metric] }}%</strong><el-progress :percentage="item[metric]" :show-text="false" :stroke-width="10" /><small>计划面积 {{ item.totalArea }} 万亩</small></div></div>
    <div class="panel rank-panel"><div class="panel-title"><span class="title-text">区域排名明细</span><span class="title-extra">当前指标：{{ metricName }}</span></div><el-table v-loading="loading" :data="sortedData" stripe><template #empty><el-empty description="暂无排行数据" /></template><el-table-column label="排名" width="80" align="center"><template #default="{$index}"><span class="rank-no" :class="`rank-${$index+1}`">{{ $index+1 }}</span></template></el-table-column><el-table-column prop="name" label="地区" min-width="130" /><el-table-column prop="totalArea" label="计划面积(万亩)" width="145" align="right" /><el-table-column label="当前指标" min-width="260"><template #default="{row}"><el-progress :percentage="row[metric]" :stroke-width="12" :color="progressColor(row[metric])" /></template></el-table-column><el-table-column prop="implementRate" label="落实率" width="90" /><el-table-column prop="sowRate" label="播种率" width="90" /><el-table-column prop="harvestRate" label="收获率" width="90" /><el-table-column label="评价" width="170"><template #default="{row}"><el-tag :type="row[metric]>=85?'success':row[metric]>=70?'warning':'danger'">{{ row[metric]>=85?'领先':row[metric]>=70?'正常':'需调度' }}</el-tag><el-button v-if="row[metric] < 70" link type="danger" @click="openSupervise(row)">发起督办</el-button><el-button v-else link type="primary" @click="drillDown(row.code)">下钻</el-button></template></el-table-column></el-table></div><el-dialog v-model="superviseVisible" title="落后单位督办" width="520px"><el-alert :title="`${superviseTarget?.name || ''} 当前${metricName}为 ${superviseTarget?.[metric] || 0}%`" type="warning" :closable="false"/><el-form ref="superviseFormRef" :model="superviseForm" :rules="superviseRules" label-width="90px" class="supervise-form"><el-form-item label="督办要求" prop="requirement"><el-input v-model="superviseForm.requirement" type="textarea" :rows="3" placeholder="填写整改要求和反馈时限"/></el-form-item><el-form-item label="反馈期限" prop="deadline"><el-date-picker v-model="superviseForm.deadline" value-format="YYYY-MM-DD" type="date" style="width:100%"/></el-form-item></el-form><template #footer><el-button @click="superviseVisible=false">取消</el-button><el-button type="primary" @click="submitSupervise">发送督办</el-button></template></el-dialog>
  </div>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'; import { ElMessage } from 'element-plus'; import StatCard from '@/components/common/StatCard.vue'; import { useUserStore } from '@/stores/user'; import { createPlanSupervise, fetchRankData } from '@/api/gpm'
const userStore=useUserStore(); const rankData=ref([]); const loading=ref(false); const metric=ref('implementRate'); const selectedRegionCode=ref(''); const selectedRegion=ref(null); const superviseVisible=ref(false); const superviseTarget=ref(null); const superviseFormRef=ref(); const superviseForm=reactive({ requirement: '请分析进度落后原因，制定追赶措施并按期反馈。', deadline: '2026-10-20' }); const superviseRules={ requirement:[{ required:true, message:'请填写督办要求', trigger:'blur' }], deadline:[{ required:true, message:'请选择反馈期限', trigger:'change' }] }; const sortedData=computed(()=>[...rankData.value].sort((a,b)=>b[metric.value]-a[metric.value])); const metricName=computed(()=>({implementRate:'落实率',sowRate:'播种率',harvestRate:'收获率'}[metric.value])); const levelHint=computed(()=>userStore.role?.code==='province'?'省级查看各市':userStore.role?.code==='city'?'市级查看各县':'县级查看各乡镇'); const average=field=>rankData.value.length?Math.round(rankData.value.reduce((s,i)=>s+i[field],0)/rankData.value.length):0; const progressColor=v=>v>=85?'#2e9e5b':v>=70?'#e6a23c':'#e64545'; const loadRankData=async(role=userStore.role)=>{ loading.value=true; try { rankData.value=await fetchRankData(role) || [] } finally { loading.value=false } }; const drillDown=code=>{ const item=rankData.value.find(row=>row.code===code); if (item) { const nextLevel={ province:'city', city:'county', county:'town', town:'town' }[userStore.role?.code] || 'city'; selectedRegion.value=item; selectedRegionCode.value=code; loadRankData({ ...userStore.role, code:nextLevel, regionCode:code }) } }; const resetDrill=()=>{ selectedRegion.value=null; selectedRegionCode.value=''; loadRankData() }; const openSupervise=row=>{ superviseTarget.value=row; superviseFormRef.value?.clearValidate(); superviseVisible.value=true }; const submitSupervise=async()=>{ const valid=await superviseFormRef.value?.validate().catch(()=>false); if (!valid || !superviseTarget.value) return; const payload={ target:superviseTarget.value, requirement:superviseForm.requirement, deadline:superviseForm.deadline, metric:metric.value, metricName:metricName.value, supervisor:userStore.regionName }; const result=await createPlanSupervise(payload); if (!result.success) return ElMessage.error(result.message); superviseVisible.value=false; ElMessage.success(`已提交${superviseTarget.value.name}的督办申请`) }; onMounted(loadRankData)
</script>
<style lang="scss" scoped>.rank-page{gap:12px;overflow:auto}.page-head{display:flex;justify-content:space-between;align-items:center}.page-head h2{font-size:22px;margin-bottom:6px}.page-head p{color:var(--ah-text-secondary)}.stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.top-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.top-card{background:#fff;border-radius:9px;padding:18px;border-top:4px solid #c5cad3;box-shadow:0 1px 5px rgba(15,62,120,.08)}.top-card h3{margin:12px 0 8px}.top-card strong{display:block;font-size:28px;margin-bottom:10px;color:var(--ah-primary)}.top-card small{display:block;color:var(--ah-text-secondary);margin-top:10px}.top-1{border-color:#e5b52f}.top-2{border-color:#9fa8b8}.top-3{border-color:#bd7c4d}.medal{font-size:12px;font-weight:700;color:#876000}.rank-no{display:inline-flex;width:27px;height:27px;align-items:center;justify-content:center;border-radius:50%;background:#edf1f6;font-weight:700}.rank-1{background:#f8d56b}.rank-2{background:#d8dde6}.rank-3{background:#e8b48d}@media(max-width:1000px){.stat-grid{grid-template-columns:repeat(2,1fr)}.top-grid{grid-template-columns:1fr}.page-head{align-items:flex-start;gap:12px;flex-direction:column}}</style>
